css:
.kl-checklist { list-style: none; padding: 0; margin: 0 0 1rem; }
.kl-checklist li { display: flex; gap: 0.6rem; align-items: flex-start; margin-bottom: 0.5rem; color: #1f2937; }
.kl-checklist li::before { content: "\2713"; flex: 0 0 auto; width: 1.15rem; height: 1.15rem; border-radius: 9999px; background: #dcfce7; color: #16a34a; font-size: 0.65rem; font-weight: 800; display: inline-flex; align-items: center; justify-content: center; margin-top: 0.2rem; }

.kl-table { width: 100%; border-collapse: collapse; font-size: 0.875rem; margin: 0 0 1.25rem; }
.kl-table th { text-align: left; padding: 0.55rem 0.75rem; background: #f9fafb; color: #374151; font-weight: 600; border-bottom: 2px solid #e5e7eb; }
.kl-table td { padding: 0.5rem 0.75rem; border-bottom: 1px solid #e5e7eb; color: #1f2937; }
.kl-table tbody tr:last-child td { border-bottom: 0; }
.kl-table td:nth-child(2) { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }

.kl-figure { margin: 0 0 1.25rem; }
.kl-figure img { width: 100%; border-radius: 10px; border: 1px solid #e5e7eb; }
.kl-figure figcaption { font-size: 0.8rem; color: #6b7280; margin-top: 0.5rem; text-align: center; }

.kl-dotted-list { display: grid; grid-template-columns: 1fr 1fr; gap: 0; margin: 0 0 1.25rem; }
.kl-dl-item { padding: 0.7rem 1rem; border-bottom: 1px dotted #cbd5e1; }
.kl-dl-item:nth-child(odd) { border-right: 1px dotted #cbd5e1; }
.kl-dl-key { display: block; font-size: 0.875rem; font-weight: 600; color: #111827; }
.kl-dl-val { font-size: 0.8rem; color: #6b7280; }

.kl-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; margin: 0 0 1.25rem; }
.kl-stat { border: 1px solid #e5e7eb; border-radius: 12px; padding: 1rem 1.25rem; text-align: center; }
.kl-stat-val { display: block; font-size: 1.5rem; font-weight: 800; color: #111827; }
.kl-stat-label { font-size: 0.7rem; color: #6b7280; text-transform: uppercase; letter-spacing: 0.06em; margin-top: 0.25rem; }

.kl-testimonial { border: 1px solid #e5e7eb; border-radius: 12px; padding: 1.25rem 1.5rem; margin: 0 0 1rem; }
.kl-quote-mark { color: #2563eb; font-size: 1.5rem; font-weight: 800; }
.kl-testimonial blockquote { border: 0; padding: 0; margin: 0.25rem 0 0.75rem; font-style: normal; color: #1f2937; }
.kl-who { display: flex; align-items: center; gap: 0.6rem; }
.kl-avatar { width: 2rem; height: 2rem; border-radius: 9999px; background: #e5e7eb; display: inline-flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.8rem; color: #374151; }
.kl-name { font-size: 0.875rem; font-weight: 600; }
.kl-role { font-size: 0.75rem; color: #6b7280; }
